schemas:
{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "Apakah catering dari Wahana Totalita tersertifikasi halal?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Ya. Seluruh menu catering Wahana Totalita menggunakan bahan-bahan halal dan disiapkan oleh mitra dapur yang memperhatikan standar kehalalan. Untuk kegiatan instansi pemerintah dan BUMN, kehalalan adalah standar wajib yang selalu kami penuhi. Untuk kegiatan khusus yang memerlukan sertifikat halal resmi dari MUI, kami dapat berkoordinasi dengan mitra dapur bersertifikat MUI."
            }
        },
        {
            "@type": "Question",
            "name": "Apa saja dokumen administrasi yang tersedia untuk keperluan SPJ?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Dokumen administrasi yang kami siapkan untuk keperluan SPJ instansi: (1) Surat Penawaran Harga bermaterai; (2) RAB (Rincian Anggaran Biaya) per item; (3) Faktur Pajak (untuk pembelian di atas Rp 1 juta); (4) Kuitansi/bukti pembayaran resmi; (5) Berita Acara Serah Terima (BAST); (6) Foto pelaksanaan konsumsi/catering; (7) Daftar menu yang disajikan. Semua dokumen diterbitkan oleh PT Kreasi Ultimate Berjaya dengan legalitas lengkap."
            }
        },
        {
            "@type": "Question",
            "name": "Berapa minimum order dan jangkauan area layanan?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Minimum order: 20 box/porsi untuk snack box dan nasi box. Untuk prasmanan/buffet minimum 50 pax. Jangkauan layanan: seluruh wilayah Yogyakarta (Kota Yogyakarta, Sleman, Bantul, Kulon Progo, Gunung Kidul) dan sekitarnya termasuk Solo dan Magelang untuk pesanan besar. Pengiriman gratis dalam radius 15 km dari pusat kota Yogyakarta."
            }
        },
        {
            "@type": "Question",
            "name": "Bagaimana mekanisme pengadaan catering melalui LPSE untuk instansi pemerintah?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Wahana Totalita terdaftar di LPSE dan PADI UMKM untuk kategori Catering & Snack. Pengadaan catering untuk kegiatan dinas yang nilainya di bawah Rp 200 juta dapat dilakukan melalui pengadaan langsung (PL) — tidak perlu tender. PPK/Pejabat Pengadaan cukup menghubungi kami, kami siapkan surat penawaran, RAB, dan seluruh dokumen yang diperlukan. Proses cepat, administrasi beres, dan SPJ aman."
            }
        },
        {
            "@type": "Question",
            "name": "Apakah bisa memesan catering paket lengkap termasuk peralatan makan?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Ya. Untuk paket prasmanan dan gala dinner, kami menyediakan peralatan makan lengkap (piring, gelas, sendok, garpu), meja display, tudung saji, dan petugas serving. Untuk nasi box dan snack box, disajikan dalam kemasan siap santap. Paket all-in juga tersedia termasuk dekorasi meja makan sederhana untuk acara formal instansi."
            }
        },
        {
            "@type": "Question",
            "name": "Berapa harga snack box dan nasi box untuk rapat dinas?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Harga disesuaikan dengan menu dan volume pesanan. Kisaran harga: snack box Rp 15.000–35.000 per box, nasi box Rp 35.000–75.000 per box, prasmanan mulai Rp 50.000 per pax (tergantung menu dan jumlah). Harga sudah termasuk kemasan dan pengiriman dalam Yogyakarta. Untuk penawaran resmi dengan RAB yang dapat digunakan untuk pengajuan anggaran, silakan hubungi kami via WhatsApp."
            }
        }
    ]
}
